/**
 * The one select on the web. A real <select> (screen readers and the phone's
 * own picker keep working) in a box the kit draws: no browser arrow, the
 * kit's chevron 12px in from the right, text that clears it, and three
 * heights shared with SegmentedControl so a row of both lines up exactly:
 * sm 32px, md 36px, lg 44px. `bare` drops the box for a field a page already
 * draws (the kit Field card, the sell sheet's ledger box); that box then
 * carries the focus ring.
 */
import { useId, type ReactNode, type SelectHTMLAttributes } from 'react';


export type ControlSize = 'sm' | 'md' | 'lg';

export interface SelectOption<T extends string = string> {
  value: T;
  label: string;
  disabled?: boolean;
}

export interface SelectProps<T extends string> extends Omit<SelectHTMLAttributes<HTMLSelectElement>, 'value' | 'onChange' | 'size' | 'className'> {
  value: T;
  onChange: (v: T) => void;
  options: readonly SelectOption<T>[];
  /** The accessible name. Omit only when an outside <label htmlFor={id}> names it. */
  label?: ReactNode;
  /** 'hidden' (default) keeps the name for screen readers only. */
  labelPlacement?: 'hidden' | 'above' | 'inline';
  size?: ControlSize;
  /** Fills its container's width. */
  block?: boolean;
  bare?: boolean;
  loading?: boolean;
  testId?: string;
  /** Layout only (grow in a row); never restyle the box per page. */
  className?: string;
}

export function ChevronDown() {
  return (
    <svg className="kit-sel-ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false">
      <path d="M6 9l6 6 6-6" />
    </svg>
  );
}

export function Select<T extends string>({
  value,
  onChange,
  options,
  label,
  labelPlacement = 'hidden',
  size = 'md',
  block,
  bare,
  loading,
  testId,
  className,
  id: idProp,
  disabled,
  ...rest
}: SelectProps<T>) {
  const auto = useId();
  const id = idProp ?? auto;
  const box = (
    <span className={`kit-sel ${size}${bare ? ' bare' : ''}`}>
      <select
        {...rest}
        id={id}
        value={value}
        onChange={(e) => onChange(e.target.value as T)}
        disabled={disabled || loading}
        aria-busy={loading || undefined}
        data-testid={testId}
      >
        {options.map((o) => (
          <option key={o.value} value={o.value} disabled={o.disabled}>
            {o.label}
          </option>
        ))}
      </select>
      {loading ? <span className="kit-spin kit-sel-ico" aria-hidden="true" /> : <ChevronDown />}
    </span>
  );
  const cls = `kit-sel-f ${labelPlacement}${block ? ' block' : ''}${bare ? ' bare' : ''}${className ? ` ${className}` : ''}`;
  if (label === undefined || label === null) return <span className={cls}>{box}</span>;
  return (
    <span className={cls}>
      <label htmlFor={id} className={labelPlacement === 'hidden' ? 'kit-sr' : 'kit-sel-l'}>
        {label}
      </label>
      {box}
    </span>
  );
}
